HTML = r'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>
:root{color-scheme:dark;--bg:#07101e;--nav:#09192b;--panel:#0e2034;--panel2:#10253d;--border:#203b58;--text:#edf4ff;--muted:#91a9c7;--blue:#278bff;--purple:#6054ff;--green:#18d49a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px/1.42 Inter,Segoe UI,Arial,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #4c9cff;outline-offset:2px}.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;background:linear-gradient(110deg,#0b1d32,#091627);border-bottom:1px solid var(--border)}.brand{display:flex;gap:12px;align-items:center}.bot{font-size:31px}.brand strong{font-size:22px;letter-spacing:-.7px}.sub{font-size:11px;color:#a7bedb}.righthead{display:flex;align-items:center;gap:15px}.scanner{background:#10243a;padding:9px 15px;border-radius:8px;font-size:11px}.dot{display:inline-block;background:#00d98b;border-radius:50%;width:9px;height:9px;margin-right:7px}.avatar{background:#465cf6;border-radius:50%;padding:10px}.shell{display:grid;grid-template-columns:190px minmax(0,1fr);min-height:calc(100vh - 64px)}aside{background:linear-gradient(#0a1c31,#071626);border-right:1px solid #18344f;padding:16px 8px}nav button{display:block;width:100%;background:transparent;border:0;color:#c3d5ed;text-align:left;padding:12px 12px;border-radius:6px;margin:2px 0}nav button:hover,nav button.active{background:#152d59;color:#c1b6ff}nav button.active{border-left:4px solid #6554ff}.admin{font-size:10px;background:#a9bfff;color:#0c2253;border-radius:12px;padding:2px 6px;margin-left:5px}.content{padding:16px;min-width:0}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:12px}.panel,.stat{background:linear-gradient(140deg,#0e2237,#0c1b2d);border:1px solid #1b3754;border-radius:10px}.stat{padding:16px;min-height:94px;display:flex;gap:12px;align-items:center}.stat .ico{font-size:25px;background:#124b80;border-radius:8px;padding:11px}.stat:nth-child(2) .ico{background:#075a43}.stat:nth-child(4) .ico{background:#442065}.stat .number{font-size:25px;font-weight:750}.small{font-size:11px;color:var(--muted)}.green{color:#26e6a7}.worktop{display:grid;grid-template-columns:minmax(0,2.45fr) minmax(265px,1fr);gap:12px;margin-bottom:12px}.settings{padding:15px}.row{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.between{justify-content:space-between}.sectiontitle{font-size:15px;font-weight:750;margin:0 0 12px}.settingsgrid{display:grid;grid-template-columns:1.25fr .9fr .85fr;gap:12px}.settingcol{padding-right:11px;border-right:1px solid #25415d;min-width:0}.settingcol:last-child{border:0;padding:0}label{display:block;font-size:11px;color:#b8cce6;margin:8px 0 5px}select,input[type=text],input[type=number],textarea{background:#0d2034;border:1px solid #2a4968;border-radius:5px;color:#eef5ff;padding:9px;width:100%;min-width:0}textarea{min-height:70px}.pills{display:flex;flex-wrap:wrap;gap:5px;margin:8px 0}.pill{background:#143766;border:1px solid #28548b;color:#bbd5ff;border-radius:6px;padding:4px 7px;font-size:11px}.pill button{border:0;background:transparent;color:#b6c8e8;margin-left:5px}.outline,.secondary{background:#0c2036;color:#b8d4fb;border:1px solid #2c5278;border-radius:6px;padding:7px 10px}.primary{background:#5149f6;border:0;color:white;border-radius:6px;padding:10px 12px;font-weight:700}.checks{display:flex;flex-wrap:wrap;gap:6px 12px}.checks label{display:inline-flex;align-items:center;gap:4px;margin:2px 0}.checks input{accent-color:#237eff}.radio{display:block;margin:8px 0;font-size:12px}.radio input{accent-color:#2985ff}.resumes{padding:14px}.resumeitem{border:1px solid #23425f;background:#0d2035;padding:10px;border-radius:7px;margin-bottom:6px;display:flex;align-items:center;gap:9px;cursor:pointer}.resumeitem.active{border-color:#398dfb}.fileicon{font-size:22px;background:#e9f3ff;color:#164e97;border-radius:5px;padding:6px}.resumeitem strong{font-size:12px}.resumeitem .small{font-size:10px}.bottom{display:grid;grid-template-columns:minmax(0,2.45fr) minmax(265px,1fr);gap:12px}.matches{padding:0 9px 10px}.tabs{display:flex;gap:5px;border-bottom:1px solid #24415f;align-items:center;flex-wrap:wrap}.tabs button{border:0;background:transparent;color:#b0c7e7;padding:12px 10px;font-size:11px}.tabs button.active{color:white;border-bottom:3px solid #6558ff;background:#142b4d}.matchbody{display:grid;grid-template-columns:1.05fr 1fr;gap:10px;padding-top:9px}.joblist{max-height:475px;overflow:auto}.job{border:1px solid #25445f;border-radius:7px;background:#10263e;margin-bottom:7px;padding:10px;cursor:pointer}.job.active{border:2px solid #1b85ff;background:#12315a}.jobtop{display:flex;justify-content:space-between;gap:8px}.companyicon{font-size:20px;background:#e6f2ff;border-radius:5px;padding:7px;color:#174c83}.job strong{font-size:12px}.job .small{font-size:10px}.matchbadge{background:#1de0a0;color:#062b28;font-size:10px;font-weight:800;padding:4px 7px;border-radius:6px;white-space:nowrap}.tag{display:inline-block;background:#203d5f;color:#c6d9f4;font-size:10px;padding:3px 5px;border-radius:4px;margin:4px 3px 0 0}.previewtop{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px}.previewtop button{font-size:10px}.paper{height:435px;overflow:auto;background:#fff;color:#22344f;border-radius:4px;padding:22px 21px;font-size:11px;line-height:1.55}.paper h2{margin:0;font-size:19px;color:#192846}.paper h4{color:#0c4e9c;border-bottom:1px solid #d2dce8;margin:12px 0 5px;font-size:11px}.paper p{margin:5px 0}.paper ul{padding-left:16px;margin:5px 0}.details{padding:13px}.details .company{display:flex;align-items:center;gap:10px;border:1px solid #23445e;padding:12px;border-radius:7px}.details h3{margin:0 0 4px}.details ul{padding-left:17px;line-height:1.75}.actions{display:flex;gap:8px;margin-top:18px}.actions button{flex:1;min-height:64px;font-weight:800;border:0;border-radius:6px}.approve{background:#0baf77;color:white}.skip{background:#e73750;color:white}.notice{background:#122b49;border:1px solid #254a70;border-radius:6px;color:#b7d5fb;padding:9px 12px;margin-bottom:12px;font-size:11px}.muted{color:var(--muted)}.page{padding:20px;min-height:650px}.page h2{margin:0 0 10px}.table{width:100%;border-collapse:collapse;margin-top:12px}.table td,.table th{text-align:left;border-bottom:1px solid #27425d;padding:12px}.table th{color:#a4c2e5}.wide{max-width:720px}.hidden{display:none!important}.toast{position:fixed;bottom:24px;right:24px;background:#123858;border:1px solid #3c8ac4;padding:13px 17px;border-radius:8px;z-index:10;box-shadow:0 10px 30px #0008}.warn{color:#ffca77}.tiny{font-size:10px;color:#7f9cbf}.addrow{display:flex;gap:7px}.addrow input{flex:1}.addrow button{white-space:nowrap}@media(max-width:1200px){.shell{grid-template-columns:155px minmax(0,1fr)}.content{padding:10px}.worktop,.bottom{grid-template-columns:1fr}.settingsgrid{grid-template-columns:repeat(3,minmax(0,1fr))}.resumes .resumegrid{display:grid;grid-template-columns:repeat(2,1fr);gap:5px}.stats{gap:7px}}@media(max-width:760px){.top{height:auto;padding:10px}.scanner{display:none}.shell{display:block}aside{padding:5px}nav{display:flex;overflow:auto}nav button{white-space:nowrap;width:auto}.stats{grid-template-columns:repeat(2,1fr)}.settingsgrid,.matchbody{grid-template-columns:1fr}.settingcol{border:0;border-bottom:1px solid #29435c;padding-bottom:10px}.paper{height:380px}.righthead{gap:4px}}
</style></head><body>
<header class="top"><div class="brand"><div class="bot">🤖</div><div><strong>JobApply AI</strong><div class="sub">Find Better Jobs. Tailored to You. Automatically.</div></div></div><div class="righthead"><div class="scanner"><span class="dot"></span> Staging Preview<br><span class="small">Live scanner not connected</span></div><span>🔔</span><span class="avatar">DE</span><span>Demo Account ▾</span></div></header>
<div class="shell"><aside><nav id="nav"></nav></aside><main class="content" id="content"></main></div><div id="toast" class="toast hidden"></div>
<script>
const seedJobs=[
{id:1,title:'Cloud Engineer',company:'Example Cloud Systems',icon:'☁️',location:'Ottawa, ON (Hybrid)',pay:'$60–$75/hr',score:95,tags:['Azure','Entra ID','Microsoft 365','Terraform','PowerShell'],description:'Maintain Azure infrastructure, troubleshoot cloud incidents, manage Entra ID, Microsoft 365 and infrastructure automation.',required:['3+ years of Azure experience','Entra ID and Microsoft 365','Infrastructure as Code','PowerShell scripting','Cloud security and monitoring'],nice:['Kubernetes','CI/CD pipelines','AWS experience']},
{id:2,title:'Cloud Support Engineer',company:'Sample Technology Group',icon:'🛠️',location:'Toronto, ON (Remote)',pay:'$55–$70/hr',score:92,tags:['Azure','M365','Active Directory','ServiceNow','SCCM'],description:'Support Microsoft cloud services and enterprise identities, troubleshoot incidents and collaborate across support teams.',required:['Microsoft Azure and Microsoft 365','Active Directory','Incident management','Ticketing systems'],nice:['Automation experience','Cloud certifications']},
{id:3,title:'IT Systems Administrator',company:'Example Public Sector',icon:'🍁',location:'Ottawa, ON (Hybrid)',pay:'$52–$65/hr',score:88,tags:['Windows Server','Active Directory','Group Policy','SCCM','Exchange'],description:'Manage Windows servers, Active Directory, group policy and enterprise endpoint infrastructure.',required:['Windows Server','Active Directory','Group Policy','SCCM or MECM'],nice:['VMware','PowerShell']},
{id:4,title:'Cloud Infrastructure Specialist',company:'Sample Commerce Co.',icon:'⚙️',location:'Canada (Remote)',pay:'$58–$72/hr',score:85,tags:['AWS','Azure','Linux','Terraform','Kubernetes'],description:'Support and maintain cloud infrastructure, assist with automation and observability.',required:['Cloud infrastructure','Linux administration','Terraform','Monitoring'],nice:['Kubernetes','AWS']},
{id:5,title:'Application Support Specialist',company:'Example Telecom',icon:'📡',location:'Ottawa, ON (Hybrid)',pay:'$50–$62/hr',score:83,tags:['ServiceNow','SQL','Windows','M365','PowerShell'],description:'Troubleshoot business applications, coordinate escalations, and document root causes.',required:['Application support','ServiceNow','Windows','Troubleshooting'],nice:['SQL','PowerShell']}
];
const initial={page:'Dashboard',resume:'Cloud Engineer Resume',resumes:['Cloud Engineer Resume','IT Support Resume','Cybersecurity Resume','QA Analyst Resume'],titles:['Cloud Engineer','Cloud Support Engineer','Cloud System Administrator','IT Systems Administrator','DevOps Engineer'],tools:['Azure','Entra ID','Microsoft 365','Active Directory','SCCM/MECM','ServiceNow','PowerShell'],mode:'all',sites:['LinkedIn','Indeed','Glassdoor','ZipRecruiter','Government of Canada Jobs','Employer Career Websites'],customSites:'',location:'Ottawa / Gatineau',rate:50,remote:true,hybrid:true,onsite:false,selected:1,decisions:{},history:[],preview:'tailored',query:'',filter:'all'};
let state={...initial};try{const saved=JSON.parse(localStorage.getItem('jobapply_demo_v5')||'{}');state={...state,...saved}}catch(e){}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('jobapply_demo_v5',JSON.stringify(state))}catch(e){}}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.remove('hidden');setTimeout(()=>el.classList.add('hidden'),3500)}
const navItems=[['Dashboard','⌂'],['Find Jobs','⚲'],['Approval Queue','☑'],['Application History','▤'],['My Resumes','▣'],['Job Titles & Profiles','◎'],['Tools & Experience','⚒'],['Search Settings','☷'],['Account Settings','♙'],['Manage Invitations','♧']];
function renderNav(){document.getElementById('nav').innerHTML=navItems.map(([name,icon])=>`<button class="${state.page===name?'active':''}" onclick="go('${name}')">${icon} &nbsp; ${name}${name==='Manage Invitations'?'<span class="admin">Admin demo</span>':''}</button>`).join('')}
function go(page){state.page=page;save();render()}
function change(key,value){state[key]=value;save();render()}
function addTitle(){const x=document.getElementById('newTitle')?.value.trim();if(x&&!state.titles.includes(x)){state.titles.push(x);save();render()} }
function removeTitle(x){state.titles=state.titles.filter(y=>y!==x);save();render()}
function addTool(){const x=document.getElementById('newTool')?.value.trim();if(x&&!state.tools.includes(x)){state.tools.push(x);save();render()}}
function removeTool(x){state.tools=state.tools.filter(y=>y!==x);save();render()}
function addResume(){const x=document.getElementById('newResume')?.value.trim();if(x&&!state.resumes.includes(x)){state.resumes.push(x);state.resume=x;save();render();toast('Demo resume profile added. No file uploaded.')}}
function toggleSite(x){state.sites=state.sites.includes(x)?state.sites.filter(s=>s!==x):[...state.sites,x];save();render()}
function decision(type){const j=seedJobs.find(j=>j.id===state.selected);if(!j)return;state.decisions[j.id]=type;state.history.unshift({id:j.id,title:j.title,company:j.company,resume:state.resume,status:type==='approved'?'Approved — not submitted':'Skipped',date:new Date().toLocaleString(),description:j.description});save();render();toast(type==='approved'?'Demo approval recorded. No application was submitted.':'Job skipped in this demo.')}
function jobCards(){const items=seedJobs.filter(j=>state.filter==='all'||(state.filter==='pending'&&!state.decisions[j.id])||(state.filter==='approved'&&state.decisions[j.id]==='approved'));return items.map(j=>`<div class="job ${state.selected===j.id?'active':''}" onclick="change('selected',${j.id})"><div class="jobtop"><div class="row" style="align-items:flex-start;flex-wrap:nowrap"><span class="companyicon">${j.icon}</span><div><strong>${esc(j.title)}</strong><div class="small">${esc(j.company)}</div><div class="small">♧ ${esc(j.location)}</div></div></div><div style="text-align:right"><span class="matchbadge">${j.score}% Match</span><div class="small" style="margin-top:6px">💵 ${esc(j.pay)}</div></div></div><div>${j.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${state.decisions[j.id]?`<div class="tiny">${state.decisions[j.id]==='approved'?'✓ Demo approved':'⊘ Skipped'}</div>`:''}</div>`).join('')||'<p class="muted">No jobs in this demo filter.</p>'}
function paper(){const j=seedJobs.find(j=>j.id===state.selected)||seedJobs[0];const tailored=state.preview==='tailored';return `<div class="paper"><h2>DEMO CANDIDATE</h2><div style="font-size:9px">Sample City, Canada &nbsp; ◇ &nbsp; sample@example.com</div><h4>${tailored?esc(j.title.toUpperCase()):'PROFESSIONAL SUMMARY'}</h4><p>${tailored?'Illustrative tailored summary highlighting experience relevant to '+esc(j.title)+'. This is sample text, not AI-generated from an actual resume.':'Illustrative master resume summary for demonstration only.'}</p><h4>TECHNICAL SKILLS</h4><p>${(tailored?j.tags:state.tools).map(esc).join(' · ')}</p><h4>PROFESSIONAL EXPERIENCE</h4><strong>Sample Employer — Senior Technical Analyst</strong><div style="float:right;font-size:9px">2022 – Present</div><ul><li>Supported enterprise infrastructure and business-critical IT services.</li><li>${tailored?'Highlighted relevant capabilities: '+j.tags.slice(0,3).map(esc).join(', ')+'.':'Resolved technical incidents and supported enterprise users.'}</li><li>Collaborated with technical teams to investigate and resolve incidents.</li><li>Documented procedures and recurring issues.</li></ul><h4>PREVIOUS EXPERIENCE</h4><strong>Previous Sample Employer — Technical Analyst</strong><ul><li>Supported enterprise applications and identity services.</li><li>Maintained technical documentation and escalated complex incidents.</li></ul><h4>EDUCATION & CERTIFICATIONS</h4><p>Illustrative content only — replace with actual verified resume information in the production system.</p></div>`}
function dashboard(){const j=seedJobs.find(j=>j.id===state.selected)||seedJobs[0];const approved=Object.values(state.decisions).filter(x=>x==='approved').length;const pending=seedJobs.length-Object.keys(state.decisions).length;return `<div class="notice">🧪 <b>STAGING DEMO</b> — Sample employers, sample match scores, and sample resumes. No live searches, AI tailoring, user accounts, or real submissions.</div><div class="stats"><div class="stat"><span class="ico">⚲</span><div><div class="small">Jobs Found</div><div class="number">${seedJobs.length}</div><span class="green small">Sample jobs</span></div></div><div class="stat"><span class="ico">▤</span><div><div class="small">Awaiting Approval</div><div class="number">${pending}</div><span class="small">Demo queue</span></div></div><div class="stat"><span class="ico">➤</span><div><div class="small">Demo Approvals</div><div class="number">${approved}</div><span class="small">Not submitted</span></div></div><div class="stat"><span class="ico">✉</span><div><div class="small">Employer Responses</div><div class="number">0</div><span class="small">Not connected</span></div></div></div>
<div class="worktop"><section class="panel settings"><div class="sectiontitle">Job Search Settings <span class="tag">Active Profile: Demo</span></div><div class="settingsgrid"><div class="settingcol"><label>Master Resume</label><select onchange="change('resume',this.value)">${state.resumes.map(r=>`<option ${r===state.resume?'selected':''}>${esc(r)}</option>`).join('')}</select><label>Job Titles (${state.titles.length})</label><div class="pills">${state.titles.map(t=>`<span class="pill">${esc(t)} <button onclick="removeTitle('${esc(t).replace(/'/g,'\\\'')}')">×</button></span>`).join('')}</div><div class="addrow"><input id="newTitle" type="text" placeholder="Add job title"><button class="outline" onclick="addTitle()">+ Add</button></div></div><div class="settingcol"><label>Search Mode</label><div class="radio"><input type="radio" name="mode" ${state.mode==='all'?'checked':''} onchange="change('mode','all')"> All Supported Sites</div><div class="radio"><input type="radio" name="mode" ${state.mode==='specific'?'checked':''} onchange="change('mode','specific')"> Specific Sites</div><label>Job Platforms</label><div class="checks">${['LinkedIn','Indeed','Glassdoor','ZipRecruiter','Government of Canada Jobs','Employer Career Websites'].map(s=>`<label><input type="checkbox" ${state.sites.includes(s)?'checked':''} ${state.mode==='all'?'disabled':''} onchange="toggleSite('${s}')">${s}</label>`).join('')}</div>${state.mode==='specific'?`<label>Custom URLs (one per line)</label><textarea id="customSites" oninput="state.customSites=this.value;save()" placeholder="https://example.com/careers">${esc(state.customSites)}</textarea>`:''}</div><div class="settingcol"><label>Location</label><input type="text" value="${esc(state.location)}" onchange="change('location',this.value)"><label>Minimum CAD/hour</label><input type="number" min="0" value="${state.rate}" onchange="change('rate',Number(this.value))"><label>Work Arrangement</label><div class="checks"><label><input type="checkbox" ${state.remote?'checked':''} onchange="change('remote',this.checked)">Remote</label><label><input type="checkbox" ${state.hybrid?'checked':''} onchange="change('hybrid',this.checked)">Hybrid</label><label><input type="checkbox" ${state.onsite?'checked':''} onchange="change('onsite',this.checked)">On-site</label></div><button style="width:100%;margin-top:12px" class="primary" onclick="toast('Demo only: live job scanning is not connected.')">⚲ Search for Jobs</button></div></div></section>
<section class="panel resumes"><div class="row between"><div class="sectiontitle">My Resumes</div><button class="outline" onclick="go('My Resumes')">+ Add Resume</button></div><div class="resumegrid">${state.resumes.slice(0,4).map(r=>`<div class="resumeitem ${state.resume===r?'active':''}" onclick="change('resume','${esc(r).replace(/'/g,'\\\'')}')"><span class="fileicon">▤</span><div><strong>${esc(r)}</strong><div class="small">${r===state.resume?'✓ Active master resume':'Select to activate'}</div></div></div>`).join('')}</div><button class="outline" style="width:100%" onclick="go('My Resumes')">＋ Manage Resume Profiles</button></section></div>
<div class="bottom"><section class="panel matches"><div class="tabs"><button class="${state.filter==='all'?'active':''}" onclick="change('filter','all')">Job Matches (${seedJobs.length})</button><button class="${state.filter==='pending'?'active':''}" onclick="change('filter','pending')">Awaiting Approval (${pending})</button><button class="${state.filter==='approved'?'active':''}" onclick="change('filter','approved')">Demo Approved (${approved})</button></div><div class="matchbody"><div class="joblist">${jobCards()}</div><div><div class="previewtop"><strong>Tailored Resume Preview</strong><div class="row"><button class="${state.preview==='original'?'primary':'secondary'}" onclick="change('preview','original')">Original</button><button class="${state.preview==='tailored'?'primary':'secondary'}" onclick="change('preview','tailored')">Tailored</button></div></div>${paper()}</div></div></section><section class="panel details"><div class="row between"><div class="sectiontitle">Job Details</div><button class="outline" onclick="toast('No live posting URL: this is a sample job.')">↗ Original Posting</button></div><div class="company"><span class="companyicon">${j.icon}</span><div><h3>${esc(j.title)}</h3><div class="small">${esc(j.company)}</div></div></div><p class="small">♧ ${esc(j.location)} · Sample full-time role</p><p class="green">💵 ${esc(j.pay)}</p><strong>Key Requirements</strong><ul>${j.required.map(x=>`<li>✓ ${esc(x)}</li>`).join('')}</ul><strong>Nice to Have</strong><ul>${j.nice.map(x=>`<li>◯ ${esc(x)}</li>`).join('')}</ul><p class="small">${esc(j.description)}</p><div class="actions"><button class="approve" onclick="decision('approved')">➤ Approve<br><span style="font-size:10px">Demo only — no submission</span></button><button class="skip" onclick="decision('skipped')">✖ Skip</button></div></section></div>`}
function simplePage(){let p=state.page;if(p==='Application History')return `<section class="panel page"><h2>Application History</h2><p class="muted">Saved decisions in this browser only. Demo approvals are not submitted applications.</p><input type="text" id="historyQuery" placeholder="Search title, company, resume..." oninput="filterHistory(this.value)"><div id="historyTable">${historyRows('')}</div></section>`;if(p==='My Resumes')return `<section class="panel page"><h2>My Resumes</h2><p class="muted">Demo resume profiles. Uploading and storing actual resume files will be implemented with private user storage.</p><div class="wide">${state.resumes.map(r=>`<div class="resumeitem ${state.resume===r?'active':''}" onclick="change('resume','${esc(r).replace(/'/g,'\\\'')}')"><span class="fileicon">▤</span><strong>${esc(r)}</strong><span class="small">${state.resume===r?'— Active':''}</span></div>`).join('')}<label>Add a demo resume profile</label><div class="addrow"><input id="newResume" type="text" placeholder="e.g. Network Engineer Resume"><button class="primary" onclick="addResume()">Add Profile</button></div></div></section>`;if(p==='Job Titles & Profiles')return `<section class="panel page"><h2>Job Titles & Profiles</h2><p class="muted">Edit your target job titles for the future matching engine.</p><div class="pills">${state.titles.map(t=>`<span class="pill">${esc(t)} <button onclick="removeTitle('${esc(t).replace(/'/g,'\\\'')}')">×</button></span>`).join('')}</div><div class="addrow wide"><input id="newTitle" placeholder="Add job title"><button class="primary" onclick="addTitle()">Add Title</button></div></section>`;if(p==='Tools & Experience')return `<section class="panel page"><h2>Tools & Experience</h2><p class="muted">Demo tool library. In production, tools will be confirmed against each user's actual experience.</p><div class="pills">${state.tools.map(t=>`<span class="pill">${esc(t)} <button onclick="removeTool('${esc(t).replace(/'/g,'\\\'')}')">×</button></span>`).join('')}</div><div class="addrow wide"><input id="newTool" placeholder="Add tool or technology"><button class="primary" onclick="addTool()">Add Tool</button></div></section>`;if(p==='Manage Invitations')return `<section class="panel page"><h2>Manage Invitations</h2><p class="warn">Invite-only registration is planned but not connected.</p><p class="muted">This public staging preview does not provide user accounts or invitations. Do not enter personal email addresses here.</p><button class="secondary" disabled>Send Invitation (coming later)</button></section>`;if(p==='Account Settings')return `<section class="panel page"><h2>Account Settings</h2><p class="muted">Authentication is not implemented in this preview. All controls use local demo data.</p></section>`;if(p==='Search Settings')return `<section class="panel page"><h2>Search Settings</h2><p class="muted">Use the Dashboard search settings to select sources, locations, salary, and work arrangement. Saved in this browser only.</p><button class="primary" onclick="go('Dashboard')">Open Search Settings</button></section>`;if(p==='Find Jobs')return `<section class="panel page"><h2>Find Jobs</h2><p class="muted">The five sample jobs below demonstrate the interface. Live scanning is not connected.</p><div class="wide">${jobCards()}</div><button class="primary" onclick="go('Dashboard')">Open Dashboard & Resume Preview</button></section>`;if(p==='Approval Queue')return `<section class="panel page"><h2>Approval Queue</h2><p class="muted">Choose a sample job on the Dashboard to preview a sample resume and approve or skip.</p><div class="wide">${seedJobs.filter(j=>!state.decisions[j.id]).map(j=>`<div class="job" onclick="state.selected=${j.id};go('Dashboard')"><strong>${esc(j.title)}</strong><div class="small">${esc(j.company)} · ${j.score}% sample match</div></div>`).join('')||'No pending sample jobs.'}</div></section>`;return dashboard()}
function historyRows(q){const records=state.history.filter(h=>[h.title,h.company,h.resume,h.status].join(' ').toLowerCase().includes(q.toLowerCase()));return records.length?`<table class="table"><tr><th>Job</th><th>Resume selected</th><th>Decision</th><th>Date</th></tr>${records.map(h=>`<tr><td><b>${esc(h.title)}</b><br><span class="small">${esc(h.company)}</span><details><summary>View saved job description</summary>${esc(h.description)}</details></td><td>${esc(h.resume)}<br><span class="tiny">Demo profile name, not a stored document</span></td><td>${esc(h.status)}</td><td>${esc(h.date)}</td></tr>`).join('')}</table>`:'<p class="muted">No matching demo history yet.</p>'}
function filterHistory(q){document.getElementById('historyTable').innerHTML=historyRows(q)}
function render(){renderNav();document.getElementById('content').innerHTML=state.page==='Dashboard'?dashboard():simplePage()}
render();
</script></body></html>'''
components.html(HTML, height=1100, scrolling=True)
